package dev.mineagent.runtime.core.memory;
import com.fasterxml.jackson.databind.ObjectMapper;import dev.mineagent.runtime.core.persistence.SqliteRuntimeRepository;import java.nio.file.Path;import java.util.*;
/** Scoped, model/version-tagged semantic vectors. Hashing is not used to derive embeddings or identities. */
public final class SemanticMemoryIndex implements AutoCloseable {
 public record Document(String origin,UUID id,long revision,String text,long updatedAt,String source){}
 public record Vector(String origin,UUID id,long sourceRevision,String model,double[] values,long createdAt){public Vector{values=unit(values);}}
 private static final ObjectMapper JSON=new ObjectMapper();private final SqliteRuntimeRepository db;private final UUID world;private final String namespace,recordPrefix;
 public SemanticMemoryIndex(Path path,UUID world,UUID owner,UUID agent)throws Exception{this.db=new SqliteRuntimeRepository(path);this.world=world;namespace="semantic_memory_"+owner;recordPrefix=agent+"_";}
 private static String key(Document d){return d.origin()+"_"+d.id();}
 public Map<String,Vector> vectors(List<Document> documents,String model)throws Exception{var out=new HashMap<String,Vector>();for(var d:documents){var row=db.get(world,namespace,recordPrefix+key(d));if(row.isEmpty())continue;var v=JSON.readValue(row.get().payload(),Vector.class);if(v.id().equals(d.id())&&v.origin().equals(d.origin())&&v.sourceRevision()==d.revision()&&v.model().equals(model))out.put(key(d),v);}return out;}
 public void save(Document d,String model,double[] vector)throws Exception{var old=db.get(world,namespace,recordPrefix+key(d));long revision=old.map(r->r.revision()).orElse(0L);var value=new Vector(d.origin(),d.id(),d.revision(),model,vector,System.currentTimeMillis());if(!db.compareAndSet(world,namespace,recordPrefix+key(d),revision,JSON.writeValueAsString(value),value.createdAt()).accepted())throw new IllegalStateException("MEMORY_VECTOR_CONFLICT");}
 public static Map<String,Double> similarities(List<Document> docs,Map<String,Vector> vectors,double[] query){query=unit(query);var result=new HashMap<String,Double>();for(var d:docs){var v=vectors.get(key(d));if(v==null||v.sourceRevision()!=d.revision()||!v.id().equals(d.id())||!v.origin().equals(d.origin())||v.values().length!=query.length)continue;double dot=0;for(int i=0;i<query.length;i++)dot+=query[i]*v.values()[i];result.put(key(d)+"_r"+d.revision(),Math.clamp(dot,-1,1));}return result;}
 public static double hybrid(int lexical,Double semantic,long updatedAt,long now,String source){boolean keyword=lexical>=MemoryRelevance.MINIMUM,meaning=semantic!=null&&semantic>=.67;if(!keyword&&!meaning)return 0;double words=Math.min(1,lexical/24.0),sem=semantic==null?0:Math.max(0,(semantic-.35)/.65),age=Math.max(0,now-updatedAt)/86400000.0;double provenance=source==null||source.equals("legacy_unspecified")?0:source.contains("tool")||source.contains("player")?.06:.02;return Math.max(words,sem)+.2*Math.min(words,sem)+.06/(1+age/30)+provenance;}
 private static double[] unit(double[] input){if(input==null||input.length<2||input.length>8192)throw new IllegalArgumentException("MEMORY_EMBEDDING_DIMENSIONS");double sum=0;for(double v:input){if(!Double.isFinite(v))throw new IllegalArgumentException("MEMORY_EMBEDDING_NONFINITE");sum+=v*v;}if(sum<1e-20||!Double.isFinite(sum))throw new IllegalArgumentException("MEMORY_EMBEDDING_ZERO");double norm=Math.sqrt(sum);double[] out=input.clone();for(int i=0;i<out.length;i++)out[i]/=norm;return out;}
 public void close()throws Exception{db.close();}
}
